  }
}

/** 让酒馆重新渲染消息列表；隐藏/删除/恢复后调用。 */
async function ctxRefreshTavernUI() {
  const st = await ctxST();
  try {
    await st?.printMessages?.();
  } catch (err) {
    console.warn('[Context & API Manager] 刷新酒馆消息失败', err);
  }
