    st?.refreshSwipeButtons?.();
  } catch {
    /* ignore */
  }
}

/** 一次摘要最多处理 4 万字符：80 轮长聊天不会撑爆请求或超时。 */
const CTX_SUMMARY_CHAR_LIMIT = 40000;
const CTX_MSG_CHAR_CAP = 8000;
function ctxBatchMessages(target, limit = CTX_SUMMARY_CHAR_LIMIT) {
  const batch = [];
  let chars = 0;
  for (const message of target) {
    const size = Math.min(message.text.length, CTX_MSG_CHAR_CAP);
    if (chars + size > limit && batch.length >= 4) break;
    batch.push(message);
    chars += size;
  }
  return batch.length ? batch : target.slice(0, 4);
}

/** 压缩期间用户切了聊天：不要把旧聊天的摘要/隐藏套到新聊天上。 */
function ctxChatUnchanged(chatRef, chatId) {
  const ctx = getSTContext();
  if (!ctx) return false;
  if (chatId != null && ctx.chatId != null) {
    return String(ctx.chatId) === String(chatId);
  }
  if (Array.isArray(ctx.chat) && ctx.chat !== chatRef) return false;
  return true;
}

/** 保留最近 keepTurns 轮，其余作为压缩目标。首楼永远不压。 */
/** 生图扩展常用的图片块：<local_img>…</local_img>（也兼容 loacl_img 拼写）与 Markdown 图片。 */
const CTX_IMAGE_BLOCK_RE = /<\s*(?:local_img|loacl_img)\b[^>]*>[\s\S]*?<\s*\/\s*(?:local_img|loacl_img)\s*>/i;
const CTX_IMAGE_OPEN_RE = /<\s*\/?\s*(?:local_img|loacl_img)\b/i;
const CTX_MD_IMAGE_RE = /!\[[^\]]*\]\([^)]+\)/;
const CTX_HTML_IMAGE_RE = /<img\b/i;

function ctxHasImageContent(text) {
  const value = String(text ?? '');
  if (!value) return false;
  return CTX_IMAGE_BLOCK_RE.test(value)
    || CTX_IMAGE_OPEN_RE.test(value)
    || CTX_MD_IMAGE_RE.test(value)
    || CTX_HTML_IMAGE_RE.test(value);
}

/** 只保留图片块本身；压图模式用它替换原消息正文。 */
function ctxExtractImageBlocks(text) {
  const value = String(text ?? '');
  const blocks = [];
  const blockRe = new RegExp(CTX_IMAGE_BLOCK_RE.source, 'gi');
  const mdRe = new RegExp(CTX_MD_IMAGE_RE.source, 'g');
  const htmlRe = new RegExp(CTX_HTML_IMAGE_RE.source, 'gi');
  for (const match of value.matchAll(blockRe)) blocks.push(match[0]);
  for (const match of value.matchAll(mdRe)) blocks.push(match[0]);
  for (const match of value.matchAll(htmlRe)) blocks.push(match[0]);
  return [...new Set(blocks)].join('\n').trim();
}

function ctxPlan(keepTurns, chatInput, imagePolicy = 'keep') {
  const visible = ctxMessages(chatInput).filter((message) => !message.hidden);
  const keep = Math.max(2, Number(keepTurns) || 6) * 2;
  const rawTarget = visible
    .slice(0, Math.max(0, visible.length - keep))
    .filter((message) => message.index > 0);
  // keep：图片楼层整楼跳过；trim：图片楼层仍参与总结，但只保留图片标签
  const imageTarget = rawTarget.filter((message) => ctxHasImageContent(message.text));
  const textTarget = rawTarget.filter((message) => !ctxHasImageContent(message.text));
  const trim = imagePolicy === 'trim';
  return {
    visible,
    target: trim ? rawTarget : textTarget,
    textTarget,
    imageTarget: trim ? imageTarget : [],
    imageSkipped: trim ? [] : imageTarget,
    keep,
  };
}

async function ctxApplySummary(summary, ranges, auto, trimImages = []) {
  const chats = await ctxChats();
  const chat = getSTContext()?.chat;
  const hidden = [];
  const setHidden = async (from, to, show) => {
    if (chats?.hideChatMessageRange) {
      await chats.hideChatMessageRange(from, to, show);
      return true;
    }
    // 纯网页/测试环境没有 chats 模块时，和「只隐藏」一样直接改 is_system
    if (!Array.isArray(chat)) return false;
    for (let index = from; index <= to; index += 1) {
      if (chat[index]) chat[index].is_system = !show;
    }
    return true;
  };
  for (const [from, to] of ranges) {
    try {
      if (await setHidden(from, to, false)) hidden.push([from, to]);
    } catch (err) {
      console.warn('[Context & API Manager] 隐藏旧消息失败', err);
    }
  }
  if (!hidden.length && !trimImages.length) return false;

  const injected = await ctxSetPrompt(`【前情提要】\n${summary}`);
  if (!injected) {
    // 注入失败就回滚，别让消息被隐藏了却没有摘要
    for (const [from, to] of hidden) {
      try {
        await setHidden(from, to, true);
      } catch {
        /* ignore */
      }
    }
    return false;
  }

  const meta = ctxChatMetadata();
  if (meta) {
    const covered = ctxGroupRanges([
      ...hidden.flatMap(([from, to]) => Array.from({ length: to - from + 1 }, (_, i) => from + i)),
      ...trimImages.map((message) => message.index),
    ]);
    meta[CTX_META_KEY] = { summary, ranges: covered, start: covered[0]?.[0] ?? 0, end: covered.at(-1)?.[1] ?? 0, at: Date.now(), auto: !!auto, version: 2, imageTrims: [] };
  }
  if (trimImages.length && Array.isArray(chat)) {
    for (const message of trimImages) {
      const current = chat[message.index];
      if (!current) continue;
      const before = String(current.mes ?? '');
      const after = ctxExtractImageBlocks(before);
      if (!after || after === before) continue;
      current.mes = after;
      if (meta?.[CTX_META_KEY]) meta[CTX_META_KEY].imageTrims.push({ index: message.index, before });
    }
  }
  await ctxSaveChat();
  await ctxRefreshTavernUI();
  return true;
}

async function ctxApplyHideOnly(ranges) {
  const chats = await ctxChats();
  if (!chats?.hideChatMessageRange) {
    const chat = getSTContext()?.chat;
    if (Array.isArray(chat)) {
      for (const [from, to] of ranges) {
        for (let index = from; index <= to; index += 1) {
          if (chat[index]) chat[index].is_system = true;
        }
      }
    }
  } else {
    for (const [from, to] of ranges) {
      try {
        await chats.hideChatMessageRange(from, to, false);
      } catch (err) {
        console.warn('[Context & API Manager] 隐藏消息失败', err);
      }
    }
  }
  const meta = ctxChatMetadata();
  if (meta) {
    meta[CTX_META_KEY] = { mode: 'hide', ranges, start: ranges[0]?.[0] ?? 0, end: ranges.at(-1)?.[1] ?? 0, at: Date.now(), version: 2 };
  }
  await ctxSaveChat();
  await ctxRefreshTavernUI();
}

async function ctxCompress({ auto = false, strategy = null, preview = !auto } = {}) {
  if (ctxBusy) return null;
  if (!auto && ctxGenerating) {
    toast('正在生成回复，稍后再试');
    return null;
  }
  ctxBusy = true;
  ctxPreviewCancelled = false;
  let timer = null;
  let previewing = false;
  try {
    const settings = ctxSettings();
    const mode = strategy ?? settings.strategy ?? 'summary';
    const { chat } = await ctxResolveChat();
    const chatRef = chat;
    const chatId = getSTContext()?.chatId ?? null;
    const { visible, target, textTarget, imageTarget, imageSkipped } = ctxPlan(
      settings.keepTurns,
      chat,
      mode === 'hide' ? 'keep' : (settings.imagePolicy === 'trim' ? 'trim' : 'keep'),
    );
    if (target.length < 2) {
      if (!auto) {
        toast(imageSkipped.length
          ? `要压缩的旧消息里有 ${imageSkipped.length} 条含图片，已跳过；图片消息不会被压缩`
          : (visible.length
            ? `只有 ${visible.length} 条可见消息，至少需要 ${Number(settings.keepTurns) * 2 + 3} 条（保留 ${settings.keepTurns} 轮）才能压缩`
            : '还没有聊天记录'));
      }
      return null;
    }
    const batch = ctxBatchMessages(target);
    const batchIndex = new Set(batch.map((message) => message.index));
    const hideBatch = batch.filter((message) => !ctxHasImageContent(message.text));
    const ranges = ctxGroupRanges(hideBatch.map((message) => message.index));
    const trimImages = imageTarget.filter((message) => batchIndex.has(message.index));
    const skippedNote = imageSkipped.length
      ? `，跳过 ${imageSkipped.length} 条含图片的消息`
      : (trimImages.length ? `，压图 ${trimImages.length} 条（保留图片标签）` : '');

    if (mode === 'hide') {
      if (!ctxChatUnchanged(chatRef, chatId)) {
        if (!auto) toast('聊天已切换，本次压缩已取消');
        return null;
      }
      await ctxApplyHideOnly(ranges);
      toast(`已隐藏 ${batch.length} 条旧消息${skippedNote}`);
      if (ui.currentTab === 'context') void renderContext();
      return { ranges, count: batch.length, skipped: imageSkipped.length };
    }

    const connection = ctxActiveConnection();
    if (!connection) {
      if (!auto) toast('没有激活的 API 连接');
      return null;
    }
    const base = normalizeBaseUrl(connection.baseUrl);
    if (!base) {
      if (!auto) toast('当前连接缺少 Base URL');
      return null;
    }
    const apiBase = tavernBaseUrl(base);

    if (!auto && settings.confirmSend !== false && typeof globalThis.confirm === 'function') {
      const ok = globalThis.confirm(`总结会把选中的 ${batch.length} 条消息发送给「${connection.name || '当前连接'}」，继续？`);
      if (!ok) return null;
    }

    const before = await ctxCountTotal(visible);
    const controller = new AbortController();
    timer = setTimeout(() => controller.abort(), 60000);
    previewing = !auto && preview;
    if (previewing) ctxOpenPreview({ controller });

    const key = await ctxConnectionKey(connection);
    const previousSummary = ctxChatMetadata()?.[CTX_META_KEY]?.summary ?? '';
    const transcript = batch
      .map((message) => {
        const text = message.text.length > CTX_MSG_CHAR_CAP
          ? `${message.text.slice(0, CTX_MSG_CHAR_CAP)}…[本条已截断]`
          : message.text;
        return `${message.isUser ? '用户' : message.name}：${text}`;
      })
      .join('\n');
    const rawFetch = globalThis.__TAM_RAW_FETCH__ || fetch;
    const summaryStyle = settings.summaryStyle === 'prose' ? 'prose' : 'rows';
    const result = await ctxRequestSummary({
      connection,
      base: apiBase,
      key,
      prompt: ctxSummaryPrompt(transcript, settings.summaryChars, previousSummary, summaryStyle),
      signal: controller.signal,
      rawFetch,
    });

    let summary = ctxNormalizeSummary(result.text, summaryStyle);
    let localFallback = false;
    if (!summary) {
      if (!auto) {
        summary = ctxLocalSummary(batch, settings.summaryChars, summaryStyle);
        localFallback = !!summary;
      }
      if (!summary) {
        const hint = result.sawReasoning ? '；模型把输出预算用在了思考上' : '';
        throw new Error(`总结为空（${result.error || '模型返回空内容'}${hint}）`);
      }
    }

    if (!ctxChatUnchanged(chatRef, chatId)) {
      if (previewing) ctxClosePreview();
      if (!auto) toast('聊天已切换，本次压缩已取消');
      return null;
    }

    if (previewing) {
      const saved = hideBatch.reduce((sum, message) => sum + ctxEstimate(message.text) + 4, 0)
        + trimImages.reduce((sum, message) => sum + Math.max(0, ctxEstimate(message.text) - ctxEstimate(ctxExtractImageBlocks(message.text))), 0);
      const after = Math.max(0, before.tokens - saved + ctxEstimate(summary) + 4);
      ctxFillPreview({
        summary,
        ranges,
        count: batch.length,
        targetCount: target.length,
        before: before.tokens,
        after,
        chatRef,
        chatId,
        skipped: imageSkipped.length,
        trimImages,
        note: [
          localFallback ? '模型未返回正文，已生成本地摘要，可编辑后再应用' : '',
          imageSkipped.length ? `已跳过 ${imageSkipped.length} 条含图片的消息` : '',
          trimImages.length ? `压图 ${trimImages.length} 条：保留图片标签、压掉正文` : '',
        ].filter(Boolean).join(' · '),
      });
      return { preview: true };
    }

    const applied = await ctxApplySummary(summary, ranges, auto, trimImages);
    if (!applied) {
      if (!auto) toast('压缩未应用：无法隐藏消息');
      return null;
    }
    const extra = batch.length < target.length ? `（本次处理最早的 ${batch.length} 条）` : '';
    toast(auto
      ? `已自动压缩 ${batch.length} 条旧消息${skippedNote}${extra}`
      : `已压缩 ${batch.length} 条 · 总结 ${summary.length} 字${skippedNote}${extra}`);
    if (ui.currentTab === 'context') void renderContext();
    return { summary, ranges, count: batch.length };
  } catch (err) {
    if (previewing) ctxClosePreview();
    if (err?.name === 'AbortError' && ctxPreviewCancelled) {
      if (!auto) toast('已取消压缩');
      return null;
    }
    const message = err?.name === 'AbortError' ? '压缩请求超时（60 秒）' : String(err?.message ?? err);
    pushError('ctx.compress', message);
    if (!auto) toast(`压缩失败：${message}`);
    return null;
  } finally {
    if (timer) clearTimeout(timer);
    ctxBusy = false;
  }
}

let ctxPreviewState = null;
let ctxPreviewAbort = null;
let ctxPreviewCancelled = false;

function ctxClosePreview(cancel = false) {
  if (cancel) {
    ctxPreviewCancelled = true;
    try { ctxPreviewAbort?.abort(); } catch { /* ignore */ }
  }
  ctxPreviewAbort = null;
  const node = $id('tam-ctx-preview');
  if (node) node.remove();
  ctxPreviewState = null;
}

/** 先弹预览（生成中可取消），再决定是否应用。 */
function ctxOpenPreview({ controller }) {
  ctxClosePreview();
  const overlay = el('div', { id: 'tam-ctx-preview' });
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) ctxClosePreview(true);
  });
  const textarea = el('textarea', {
    id: 'tam-ctx-preview-text',
    disabled: 'disabled',
    placeholder: '正在生成总结…',
  });
  const est = el('div', { id: 'tam-ctx-preview-est' }, '正在请求总结，最多 60 秒…');
  const actions = el('div', { class: 'tam-ctxactions' });
  const cancel = el('button', { class: 'tam-ghost', type: 'button', onclick: () => ctxClosePreview(true) }, '取消');
  const regen = el('button', {
    class: 'tam-ghost',
    type: 'button',
    disabled: 'disabled',
    onclick: () => {
      ctxClosePreview();
      void ctxCompress({ preview: true });
    },
  }, '重新生成');
  const apply = el('button', {
    class: 'tam-primary',
    type: 'button',
    disabled: 'disabled',
    onclick: () => {
      const state = ctxPreviewState;
      if (!state) return;
      const text = state.textarea.value.trim();
      if (!text) {
        toast('总结不能为空');
        return;
      }
      if (!ctxChatUnchanged(state.chatRef, state.chatId)) {
        toast('聊天已切换，已取消');
        ctxClosePreview();
        return;
      }
      const { ranges, count } = state;
      ctxClosePreview();
      void (async () => {
        const applied = await ctxApplySummary(text, ranges, false, state.trimImages ?? []);
        if (!applied) {
          toast('压缩未应用：无法隐藏消息');
          return;
        }
        toast(`已压缩 ${count} 条${state.skipped ? `，跳过 ${state.skipped} 条含图片的消息` : ''} · 总结 ${text.length} 字`);
        if (ui.currentTab === 'context') void renderContext();
      })();
    },
  }, '应用压缩');
  actions.append(cancel, regen, apply);

  overlay.append(
    el('div', { id: 'tam-ctx-preview-card' },
      el('h3', {}, '压缩预览'),
      el('p', { class: 'tam-hint' }, '确认总结后再隐藏原消息；可以手动修改，取消不会改动聊天。'),
      textarea,
      est,
      actions,
    ),
  );
  ui.root.append(overlay);
  ctxPreviewState = { textarea, est, apply, regen, cancel, ranges: [], count: 0, skipped: 0, chatRef: null, chatId: null };
  if (controller) {
    ctxPreviewAbort = controller;
    controller.signal.addEventListener('abort', () => ctxClosePreview(), { once: true });
    ctxPreviewState.cancel.onclick = () => {
      try { controller.abort(); } catch { /* ignore */ }
      ctxClosePreview(true);
    };
  }
}

function ctxFillPreview({ summary, ranges, count, targetCount, before, after, chatRef, chatId, skipped = 0, trimImages = [], note = '' }) {
  const state = ctxPreviewState;
  if (!state) return;
  state.ranges = ranges;
  state.count = count;
  state.skipped = skipped;
  state.trimImages = trimImages;
  state.chatRef = chatRef;
  state.chatId = chatId;
  state.textarea.disabled = false;
  state.textarea.value = summary;
  state.est.textContent = `预计 ${before.toLocaleString()} → ${after.toLocaleString()} tokens · 处理 ${count}${targetCount > count ? `/${targetCount}` : ''} 条${note ? ` · ${note}` : ''}`;
  state.apply.removeAttribute('disabled');
  state.regen.removeAttribute('disabled');
  state.textarea.focus();
}

/** 旧版本/损坏的 meta 可能没有 ranges，或 start/end 不是数字；先用它兜底。 */
function ctxSafeRanges(meta, chatLength) {
  const raw = Array.isArray(meta?.ranges) && meta.ranges.length
    ? meta.ranges
    : [[meta?.start, meta?.end]];
  const list = [];
  for (const pair of raw) {
    const from = Number(Array.isArray(pair) ? pair[0] : NaN);
    const to = Number(Array.isArray(pair) ? pair[1] : NaN);
    if (!Number.isFinite(from) || !Number.isFinite(to)) continue;
    const start = Math.max(0, Math.min(chatLength - 1, Math.floor(from)));
    const end = Math.max(start, Math.min(chatLength - 1, Math.floor(to)));
    if (end >= start) list.push([start, end]);
  }
  return list;
}

async function ctxUndo() {
  const meta = ctxChatMetadata()?.[CTX_META_KEY];
  if (!meta) {
    toast('没有可撤销的压缩');
    return;
  }
  const { chat } = await ctxResolveChat();
  const ranges = ctxSafeRanges(meta, chat.length);
  if (!ranges.length) {
    toast('压缩记录缺少有效楼层，无法自动恢复；请手动取消隐藏');
    return;
  }
  // 压图模式改过消息正文，先恢复原文
  if (Array.isArray(meta.imageTrims)) {
    for (const trim of meta.imageTrims) {
      const target = chat[Number(trim?.index)];
      if (target && typeof trim?.before === 'string') target.mes = trim.before;
    }
  }
  const chats = await ctxChats();
  if (!chats?.hideChatMessageRange) {
    toast('宿主不支持取消隐藏');
    return;
  }
  try {
    for (const [from, to] of ranges) {
      await chats.hideChatMessageRange(from, to, true);
    }
    await ctxSetPrompt('');
    delete ctxChatMetadata()[CTX_META_KEY];
    await ctxSaveChat();
    const count = ranges.reduce((sum, [from, to]) => sum + (to - from + 1), 0);
    toast(`已恢复 ${count} 条消息`);
    if (ui.currentTab === 'context') void renderContext();
  } catch (err) {
    toast(`撤销失败：${String(err?.message ?? err)}`);
  }
}

/** 查看 / 编辑当前聊天已应用的压缩总结。 */
let ctxSummaryState = null;

function ctxCloseSummaryView() {
  const node = $id('tam-ctx-summary-view');
  if (node) node.remove();
  ctxSummaryState = null;
}

function ctxOpenSummaryView() {
  const meta = ctxChatMetadata()?.[CTX_META_KEY];
  if (!meta?.summary) {
    toast('还没有压缩总结');
    return;
  }
  ctxCloseSummaryView();
  const chatRef = getSTContext()?.chat;
  const chatId = getSTContext()?.chatId ?? null;
  const ranges = ctxSafeRanges(meta, Array.isArray(chatRef) ? chatRef.length : 0);
  if (!ranges.length) {
    toast('压缩记录缺少有效楼层，无法定位原消息');
    return;
  }
  const count = ranges.reduce((sum, [from, to]) => sum + Math.max(0, to - from + 1), 0);
  const overlay = el('div', { id: 'tam-ctx-summary-view' });
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) ctxCloseSummaryView();
  });

  const table = el('div', { class: 'tam-summary-table', id: 'tam-ctx-summary-rows' });
  const emptyHint = el('p', { class: 'tam-hint', id: 'tam-ctx-summary-empty' });
  const textarea = el('textarea', { id: 'tam-ctx-summary-text' });
  textarea.value = meta.summary;

  const est = el('div', { id: 'tam-ctx-summary-est', class: 'tam-ctxsum-est' });
  const updateEst = () => {
    const text = textarea.value.trim();
    const rows = ctxParseSummaryRows(text);
    est.textContent = rows.length
      ? `${rows.length} 条 · ${text.length} 字 · 约 ${ctxEstimate(text)} tokens`
      : `${text.length} 字 · 约 ${ctxEstimate(text)} tokens`;
  };

  const renderRows = () => {
    const rows = ctxParseSummaryRows(textarea.value);
    table.textContent = '';
    if (!rows.length) {
      table.classList.add('tam-hidden');
      emptyHint.classList.remove('tam-hidden');
      emptyHint.textContent = '当前是段落式总结；点「整理成条目」可转成表格，或直接编辑下方原文。';
      updateEst();
      return;
    }
    table.classList.remove('tam-hidden');
    emptyHint.classList.add('tam-hidden');
    table.append(
      el('div', { class: 'tam-summary-row is-head' },
        el('span', {}, '#'),
        el('span', {}, '地点'),
        el('span', {}, '事件'),
        el('span', {}, '结果'),
      ),
      ...rows.map((row) => el('div', { class: 'tam-summary-row' },
        el('span', { class: 'is-no' }, String(row.no)),
        el('span', {}, row.place),
        el('span', {}, row.event),
        el('span', {}, row.result),
      )),
    );
    updateEst();
  };

  textarea.addEventListener('input', renderRows);

  const tidy = el('button', {
    class: 'tam-ghost',
    type: 'button',
    id: 'tam-ctx-summary-tidy',
    onclick: () => {
      const rows = ctxParseSummaryRows(textarea.value);
      if (rows.length) {
        textarea.value = ctxFormatSummaryRows(rows);
        toast('已经按条目重排');
      } else {
        const legacy = ctxLegacyToRows(textarea.value);
        if (!legacy.length) {
          toast('没有可整理的内容');
          return;
        }
        textarea.value = ctxFormatSummaryRows(legacy);
        toast(`已拆成 ${legacy.length} 条，可继续修改`);
      }
      renderRows();
    },
  }, '整理成条目');

  const save = el('button', {
    class: 'tam-primary',
    type: 'button',
    onclick: async () => {
      const style = ctxSettings().summaryStyle === 'prose' ? 'prose' : 'rows';
      const text = ctxNormalizeSummary(textarea.value.trim(), style);
      if (!text) {
        toast('总结不能为空');
        return;
      }
      if (text.length > 4000) {
        toast('总结超过 4000 字，请先精简再保存');
        return;
      }
      const current = ctxChatMetadata()?.[CTX_META_KEY];
      if (!current) {
        toast('当前聊天没有压缩记录');
        return;
      }
      if (!ctxChatUnchanged(chatRef, chatId)) {
        toast('聊天已切换，已取消');
        ctxCloseSummaryView();
        return;
      }
      const injected = await ctxSetPrompt(`【前情提要】\n${text}`);
      current.summary = text;
      current.at = Date.now();
      await ctxSaveChat();
      ctxCloseSummaryView();
      toast(injected ? `已保存总结 · ${text.length} 字` : '总结已保存，但注入失败，下一条消息可能不带前情提要');
      if (ui.currentTab === 'context') void renderContext();
    },
  }, '保存修改');
  const restore = el('button', {
    class: 'tam-ghost is-danger',
    type: 'button',
    onclick: () => {
      const ok = typeof globalThis.confirm === 'function'
        ? globalThis.confirm(`恢复 #${ranges[0][0]}–#${ranges[ranges.length - 1][1]} 的消息并删除总结？`)
        : true;
      if (!ok) return;
      ctxCloseSummaryView();
      void ctxUndo();
    },
  }, '恢复原消息');
  const close = el('button', {
    class: 'tam-ghost',
    type: 'button',
    onclick: () => ctxCloseSummaryView(),
  }, '关闭');

  overlay.append(
    el('div', { id: 'tam-ctx-summary-card' },
      el('h3', {}, '压缩总结'),
      el('p', { class: 'tam-hint' },
        `覆盖 #${ranges[0][0]}–#${ranges[ranges.length - 1][1]} · ${count} 条已隐藏 · ${meta.auto ? '自动' : '手动'}压缩 · ${new Date(Number(meta.at) || Date.now()).toLocaleString()}`),
      table,
      emptyHint,
      el('div', { class: 'tam-summary-editor' },
        el('div', { class: 'tam-summary-editor-head' },
          el('span', {}, '编辑原文（序号｜地点｜人物｜事件｜结果）'),
          tidy,
        ),
        textarea,
      ),
      est,
      el('div', { class: 'tam-ctxactions' }, close, restore, save),
    ),
  );
  ui.root.append(overlay);
  ctxSummaryState = { overlay, textarea, table };
  renderRows();
  textarea.focus();
}

/** 一键取消所有隐藏，并清掉注入的摘要。 */
async function ctxUnhideAll() {
  const { chat } = await ctxResolveChat();
  if (!chat.length) {
    toast('还没有聊天记录');
    return;
  }
  const meta = ctxChatMetadata();
  if (Array.isArray(meta?.[CTX_META_KEY]?.imageTrims)) {
    for (const trim of meta[CTX_META_KEY].imageTrims) {
      const target = chat[Number(trim?.index)];
      if (target && typeof trim?.before === 'string') target.mes = trim.before;
    }
  }
  const chats = await ctxChats();
  if (chats?.hideChatMessageRange) {
    try {
      await chats.hideChatMessageRange(0, chat.length - 1, true);
    } catch (err) {
      toast(`取消隐藏失败：${String(err?.message ?? err)}`);
      return;
    }
  } else {
    for (const message of chat) {
      if (message) message.is_system = false;
    }
    await ctxSaveChat();
  }
  await ctxSetPrompt('');
  if (meta) delete meta[CTX_META_KEY];
  await ctxSaveChat();
  ctxSelected.clear();
  toast('已取消全部隐藏');
  if (ui.currentTab === 'context') void renderContext();
}

/** 切换聊天后把摘要重新注入（extension prompt 不随聊天保存）。 */
let ctxApiSyncTimer = null;

/** 根据当前酒馆设置找回对应的插件连接；预设切换后防止 activeId 一直指向旧连接。 */
async function ctxSyncActiveFromTavern() {
  try {
    const cs = getChatSettings();
    if (!cs) return;
    const settings = loadSettings();
    const items = Array.isArray(settings.items) ? settings.items : [];
    if (!items.length) return;
    const match = ctxConnectionForSettings(items, cs);
    if (!match) {
      if (settings.activeId) {
        settings.activeId = null;
        saveSettings();
        ui.setActiveRow('');
      }
      return;
    }
    if (settings.activeId === match.id) return;
    settings.activeId = match.id;
    saveSettings();
    ui.setActiveRow(match.id);
  } catch (err) {
    pushError('api.sync', err);
  }
}

function ctxScheduleApiSync() {
  clearTimeout(ctxApiSyncTimer);
  ctxApiSyncTimer = setTimeout(() => { void ctxSyncActiveFromTavern(); }, 500);
}

async function ctxReapply() {
  const meta = ctxChatMetadata()?.[CTX_META_KEY];
  if (!meta?.summary) return;
  await ctxSetPrompt(`【前情提要】\n${meta.summary}`);
}

function ctxAutoDecision({ settings, visible, meta, tokens, usable }) {
  const lastEnd = Number(meta?.end ?? -1);
  const roundsSince = visible.filter((message) => message.index > lastEnd && !message.isUser).length;
  const every = Number(settings?.autoEvery) || 0;
  const byCount = every > 0 && roundsSince >= every;
  const byRatio = Number(usable) > 0 && Number(tokens) / Number(usable) >= Number(settings?.threshold || 0.8);
  return { byCount, byRatio, trigger: byCount || byRatio, roundsSince };
}

async function ctxAutoMaybe() {
  const settings = ctxSettings();
  if (!settings.auto || ctxBusy || ctxGenerating) return;
  if (Date.now() - ctxLastAutoAt < 15000) return;
  const { chat } = await ctxResolveChat();
  const { visible, target } = ctxPlan(settings.keepTurns, chat);
  if (target.length < 2) return;

  const budget = ctxBudget();
  const prefix = ctxMeasuredRequest()?.prefix ?? 0;
  // 前缀本身就把预算吃满时，压缩历史救不回来，别每轮白压一次
  if (prefix >= budget.usable * 0.95) return;

  const meta = ctxChatMetadata()?.[CTX_META_KEY];
  let tokens = 0;
  const decision = ctxAutoDecision({ settings, visible, meta, tokens, usable: budget.usable });
  if (!decision.byCount) {
    const total = await ctxCountTotal(visible);
    // 只数聊天会漏掉预设/角色卡/世界书，自动压缩永远不触发；加上实测前缀
    tokens = total.tokens + prefix;
    Object.assign(decision, ctxAutoDecision({ settings, visible, meta, tokens, usable: budget.usable }));
  }
  if (!decision.trigger) return;

  ctxLastAutoAt = Date.now();
  await ctxCompress({ auto: true });
}

async function ctxInstallHooks() {
  try {
    // 真实 usage 写入 lastRequest 后再触发自动压缩，避免 800ms 时数据还没到
    globalThis.addEventListener?.('tam:request-measured', () => {
      clearTimeout(ctxMeasureTimer);
      ctxMeasureTimer = setTimeout(() => { void ctxAutoMaybe(); }, 1500);
    });
    const st = await ctxST();
    const events = st?.event_types ?? {};
    // 预设切换会改酒馆的 API 设置；把插件的「当前连接」同步回匹配项，避免两边显示错位
    const presetEvent = events.OAI_PRESET_CHANGED_AFTER ?? 'oai_preset_changed_after';
    st?.eventSource?.on?.(presetEvent, () => {
      ctxScheduleApiSync();
      if (ui.currentTab === 'context') setTimeout(() => { void renderContext(); }, 400);
    });
    st?.eventSource?.on?.(events.SETTINGS_UPDATED, ctxScheduleApiSync);
    st?.eventSource?.on?.(events.GENERATION_STARTED, () => {
      ctxGenerating = true;
    });
    st?.eventSource?.on?.(events.GENERATION_STOPPED, () => {
      ctxGenerating = false;
    });
    st?.eventSource?.on?.(events.GENERATION_ENDED, () => {
      ctxGenerating = false;
      // 供应商没返回 usage 时不会触发 measured 事件，保留一次兜底
      setTimeout(() => { void ctxAutoMaybe(); }, 1200);
    });
    st?.eventSource?.on?.(events.MESSAGE_RECEIVED, () => {
      if (ui.currentTab === 'context') setTimeout(() => { void renderContext(); }, 400);
    });
    st?.eventSource?.on?.(events.CHAT_CHANGED, () => {
      ctxSelected.clear();
      ctxTokenMap.clear();
      ctxGenerating = false;
      ctxCloseSummaryView();
      setTimeout(() => {
        void ctxReapply();
        if (ui.currentTab === 'context') void renderContext();
      }, 500);
    });
  } catch (err) {
    console.warn('[Context & API Manager] 上下文事件订阅失败', err);
  }
}

/** 把零散的消息 id 合并成连续区间，减少 host 调用次数。 */
function ctxGroupRanges(input) {
  const ids = [...new Set(input)].sort((a, b) => a - b);
  if (!ids.length) return [];
  const ranges = [];
  let start = ids[0];
  let prev = ids[0];
  for (const id of ids.slice(1)) {
    if (id === prev + 1) {
      prev = id;
    } else {
      ranges.push([start, prev]);
      start = id;
      prev = id;
    }
  }
  ranges.push([start, prev]);
  return ranges;
}

async function ctxChats() {
  try {
    if (!ctxChatsModulePromise) ctxChatsModulePromise = import('/scripts/chats.js');
    return await ctxChatsModulePromise;
  } catch (err) {
    console.warn('[Context & API Manager] 加载 chats.js 失败', err);
    return null;
  }
}

/** 把选中的消息按连续区间隐藏 / 取消隐藏。 */
async function ctxHideSelected(hide) {
  if (ctxBusy || ctxGenerating) {
    toast('正在生成或压缩，稍后再试');
    return;
  }
  const { chat } = await ctxResolveChat();
  let ids = [...ctxSelected].filter((index) => index >= 0 && index < chat.length).sort((a, b) => a - b);
  if (!ids.length) return;
  let imageSkipped = 0;
  if (hide) {
    const before = ids.length;
    ids = ids.filter((index) => !ctxHasImageContent(chat[index]?.mes));
    imageSkipped = before - ids.length;
    if (!ids.length) {
      toast('选中的楼层都含图片；隐藏整楼会让图片消失，已跳过');
      return;
    }
  }
  const chats = await ctxChats();
  if (!chats?.hideChatMessageRange) {
    const chat = getSTContext()?.chat;
    if (!Array.isArray(chat)) {
      toast('宿主不支持隐藏消息');
      return;
    }
    for (const index of ids) {
      if (chat[index]) chat[index].is_system = hide;
    }
    await ctxSaveChat();
    await ctxRefreshTavernUI();
    ctxSelected.clear();
    toast(`${hide ? '已隐藏' : '已取消隐藏'} ${ids.length} 条${imageSkipped ? `，跳过 ${imageSkipped} 条含图片的楼层` : ''}`);
    if (ui.currentTab === 'context') void renderContext();
    return;
  }
  const ranges = ctxGroupRanges(ids);
  for (const [from, to] of ranges) {
    await chats.hideChatMessageRange(from, to, !hide);
  }
  await ctxRefreshTavernUI();
  ctxSelected.clear();
  toast(`${hide ? '已隐藏' : '已取消隐藏'} ${ids.length} 条${imageSkipped ? `，跳过 ${imageSkipped} 条含图片的楼层` : ''}`);
  if (ui.currentTab === 'context') void renderContext();
}

/** 删除选中的消息；删除前存一份快照，可从“恢复最近删除”找回。 */
async function ctxDeleteSelected() {
  if (ctxBusy || ctxGenerating) {
    toast('正在生成或压缩，稍后再试');
    return;
  }
  const { chat } = await ctxResolveChat();
  const ids = [...ctxSelected]
    .filter((index) => index > 0 && index < chat.length)
    .sort((a, b) => b - a);
  if (ctxSelected.has(0)) toast('首楼不能删除，只能隐藏');
  if (!ids.length) return;
  const confirmed = typeof globalThis.confirm === 'function'
    ? globalThis.confirm(`删除 ${ids.length} 条消息？删除后可在「恢复最近删除」里找回。`)
    : true;
  if (!confirmed) return;
  const st = await ctxST();
  if (!st?.deleteMessage || !chat.length) {
    toast('宿主不支持删除消息');
    return;
  }
  const snapshot = ids
    .map((index) => {
      const message = chat[index];
      if (!message) return null;
      return {
        index,
        is_user: !!message.is_user,
        is_system: !!message.is_system,
        name: message.name,
        send_date: message.send_date,
        mes: String(message.mes ?? '').slice(0, 20000),
      };
    })
    .filter(Boolean)
    .slice(0, 200);
  for (const index of ids) {
    await st.deleteMessage(index);
  }
  const meta = ctxChatMetadata();
  if (meta) {
    const list = Array.isArray(meta.tamCtxDeleted) ? meta.tamCtxDeleted : [];
    meta.tamCtxDeleted = [{ at: Date.now(), messages: snapshot }, ...list].slice(0, 3);
  }
  try {
    await st.saveChatConditional?.();
  } catch {
    /* ignore */
  }
  await ctxRefreshTavernUI();
  ctxSelected.clear();
  toast(ids.length > 200
    ? `已删除 ${ids.length} 条（仅最近 200 条可恢复）`
    : `已删除 ${ids.length} 条`);
  if (ui.currentTab === 'context') void renderContext();
}

/** 把最近一次删除按原楼层插回去（id 位移后尽量靠近原位）。 */
async function ctxRestoreDelete() {
  const meta = ctxChatMetadata();
  const list = Array.isArray(meta?.tamCtxDeleted) ? meta.tamCtxDeleted : [];
  const snapshot = list[0];
  if (!snapshot?.messages?.length) {
    toast('没有可恢复的删除');
    return;
  }
  const { chat } = await ctxResolveChat();
  const st = await ctxST();
  if (!chat.length || !st?.saveChatConditional) {
    toast('宿主不支持恢复');
    return;
  }
  for (const item of [...snapshot.messages].sort((a, b) => a.index - b.index)) {
    chat.splice(Math.min(item.index, chat.length), 0, {
      is_user: !!item.is_user,
      is_system: !!item.is_system,
      name: item.name,
      mes: item.mes,
      send_date: item.send_date,
    });
  }
  await st.saveChatConditional();
  if (meta) meta.tamCtxDeleted = list.slice(1);
  await ctxRefreshTavernUI();
  toast(`已恢复 ${snapshot.messages.length} 条`);
  if (ui.currentTab === 'context') void renderContext();
}

/* ---- 上下文 tab ---- */

function ctxRow(message, tokens) {
  const selected = ctxSelected.has(message.index);
  return el('div', {
    class: `tam-ctxrow${message.hidden ? ' tam-ctxrow-hidden' : ''}${selected ? ' is-sel' : ''}`,
    dataset: { idx: String(message.index) },
    onclick: () => {
      if (ctxSelected.has(message.index)) ctxSelected.delete(message.index);
      else ctxSelected.add(message.index);
      ctxSyncSelection();
    },
  },
    el('span', { class: `tam-ctxcb${selected ? ' is-on' : ''}` }),
    el('span', { class: 'tam-ctxidx' }, `#${message.index}`),
    el('span', { class: `tam-ctxwho${message.isUser ? ' is-user' : ''}` }, message.isUser ? '你' : message.name),
    el('span', { class: 'tam-ctxtext' }, message.text.length > 160 ? `${message.text.slice(0, 160)}…` : message.text),
    el('span', { class: 'tam-ctxtok' }, `${tokens}`),
  );
}

/** 选中消息的 token 估算：列表内用精确值，列表外用估算补齐。 */
function ctxSelectionTokens(ids) {
  return ids.reduce((sum, id) => {
    const known = ctxTokenMap.get(id);
    return sum + (Number.isFinite(known) ? known : ctxEstimate(ctxTextMap.get(id) ?? ''));
  }, 0);
}

/** 只改选中样式，不重新计数，避免点一下整页抖一下。 */
function ctxSyncSelection() {
  const rows = document.querySelectorAll('#tam-ctx-list .tam-ctxrow');
  for (const row of rows) {
    const index = Number(row.dataset.idx);
    const on = ctxSelected.has(index);
    row.classList.toggle('is-sel', on);
    row.querySelector('.tam-ctxcb')?.classList.toggle('is-on', on);
  }
  const bar = $id('tam-ctx-selbar');
  if (!bar) return;
  const ids = [...ctxSelected];
  const tokens = ctxSelectionTokens(ids);
  bar.classList.toggle('tam-hidden', ids.length === 0);
  const info = $id('tam-ctx-selinfo');
  if (info) info.textContent = `已选 ${ids.length} 条 · ${tokens.toLocaleString()} tokens`;
}

/** 按楼层区间选中（从 #a 到 #b）。 */
async function ctxRangeSelect() {
  const fromRaw = $id('tam-ctx-from')?.value ?? '';
  const toRaw = $id('tam-ctx-to')?.value ?? '';
  if (String(fromRaw).trim() === '' || String(toRaw).trim() === '') {
    toast('请先填写起止楼层');
    return null;
  }
  const from = Number(fromRaw);
  const to = Number(toRaw);
  if (!Number.isFinite(from) || !Number.isFinite(to)) {
    toast('楼层必须是数字');
    return null;
  }
  const { chat } = await ctxResolveChat();
  const max = Math.max(0, chat.length - 1);
  const start = Math.max(0, Math.min(Math.min(from, to), max));
  const end = Math.max(0, Math.min(Math.max(from, to), max));
  ctxSelected.clear();
  for (let index = start; index <= end; index += 1) ctxSelected.add(index);
  ctxSyncSelection();
  return { start, end };
}

function ctxSelect(id, options, value, onChange) {
  const select = el('select', { id, class: 'tam-ctxselect', onchange: onChange },
    ...options.map(([optionValue, label]) => el('option', { value: String(optionValue) }, label)),
  );
  select.value = String(value);
  return select;
}

let ctxRenderSeq = 0;

async function renderContext() {
  const body = ui.contextEl;
  if (!body) return;
  const seq = ++ctxRenderSeq;
  const settings = ctxSettings();
  const budget = ctxBudget();
  const { chat, source } = await ctxResolveChat();
  if (seq !== ctxRenderSeq) return;
  const all = ctxMessages(chat);

  if (!all.length) {
    body.textContent = '';
    body.append(el('p', { class: 'tam-hint' },
      source === 'empty'
        ? '没有读到聊天记录。先打开一个聊天窗口，再点这个 tab。'
        : '当前没有聊天记录。先和角色说句话，再回来压缩。'));
    return;
  }

  const visible = all.filter((message) => !message.hidden);
  const hiddenCount = all.length - visible.length;
  if (!visible.length) {
    body.textContent = '';
    body.append(
      el('p', { class: 'tam-hint' }, '所有消息都被隐藏了。'),
      el('div', { class: 'tam-ctxactions' },
        el('button', {
          class: 'tam-primary',
          type: 'button',
          onclick: () => { void ctxUnhideAll(); },
        }, '全部取消隐藏'),
      ),
    );
    return;
  }

  const total = await ctxCountTotal(visible);
  if (seq !== ctxRenderSeq) return;

  const measured = ctxMeasuredRequest();
  const requestTokens = measured?.prompt ?? total.tokens;
  const ratio = budget.usable ? requestTokens / budget.usable : 0;
  const pct = Math.max(0, Math.min(100, Math.round(ratio * 100)));
  const state = pct >= 85 ? 'danger' : pct >= 60 ? 'warn' : 'ok';
  const rows = visible.slice(-CTX_ROWS);
  const each = await ctxCountEach(rows);
  if (seq !== ctxRenderSeq) return;

  ctxTokenMap.clear();
  ctxTextMap.clear();
  all.forEach((message) => ctxTextMap.set(message.index, message.text));
  rows.forEach((message, index) => ctxTokenMap.set(message.index, each.counts[index] ?? 0));
  body.textContent = '';

  const meta = ctxChatMetadata()?.[CTX_META_KEY] ?? null;
  const deleted = ctxChatMetadata()?.tamCtxDeleted ?? [];
  const prefix = measured || total.exact ? '' : '≈';
  const selected = [...ctxSelected];

  body.append(
    el('div', { class: 'tam-ctxcard' },
      el('div', { class: 'tam-ctxhead' },
        el('div', {},
          el('span', { class: 'tam-ctxlabel' }, measured ? '上次请求' : '本次请求（仅对话）'),
          el('div', { class: 'tam-ctxnum' }, `${prefix}${requestTokens.toLocaleString()}`,
            el('small', {}, ` / ${budget.usable.toLocaleString()}`)),
        ),
        el('span', { class: 'tam-ctxpct', dataset: { state } }, `${pct}%`),
      ),
      el('div', { class: 'tam-ctxbar' },
        el('i', { class: `is-${state}`, style: `width:${pct}%` }),
      ),
      el('div', { class: 'tam-ctxmeta' },
        el('span', {}, `${all.length} 条 · ${hiddenCount} 条已隐藏 · ${source}`),
        el('span', {}, budget.override > 0 ? `预算 ${budget.limit.toLocaleString()}（手动）` : `预算 ${budget.limit.toLocaleString()}`),
      ),
      measured
        ? el('div', { class: 'tam-ctxmeta' },
          el('span', {}, `实测：对话 ${total.tokens.toLocaleString()} + 静态前缀 ${measured.prefix.toLocaleString()}`),
          el('span', {}, measured.model || ''))
        : null,
    ),
  );

  if (!measured) {
    body.append(el('p', { class: 'tam-hint' },
      '发一条消息后，这里会显示包含预设 / 角色卡 / 世界书的真实请求大小（静态前缀）。'));
  }

  const avgTokens = total.tokens / Math.max(1, visible.length);
  const keepNeed = (Number(settings.keepTurns) * 2 + 2) * avgTokens;
  if (budget.usable < keepNeed) {
    body.append(el('p', { class: 'tam-hint tam-hint-warn' },
      `当前预算装不下「保留最近 ${settings.keepTurns} 轮」，建议把保留轮数调小，或把有效预算调大。`));
  }

  const recentReplies = rows.filter((message) => !message.isUser).slice(-3);
  if (recentReplies.length) {
    const avgReplyTokens = recentReplies.reduce((sum, message) => sum + (ctxTokenMap.get(message.index) ?? 0), 0) / recentReplies.length;
    const recentUsers = rows.filter((message) => message.isUser).slice(-3);
    const avgUserTokens = recentUsers.length
      ? recentUsers.reduce((sum, message) => sum + (ctxTokenMap.get(message.index) ?? 0), 0) / recentUsers.length
      : 0;
    body.append(el('div', { class: 'tam-ctxmeta' },
      el('span', {}, `近 ${recentReplies.length} 轮平均 +${Math.round(avgReplyTokens)} tokens/条`),
      el('span', {}, `≈ +${Math.round(avgReplyTokens + avgUserTokens)}/轮`),
    ));
  }
  if (recentReplies.length) {
    const avgReply = recentReplies.reduce((sum, message) => sum + (ctxTokenMap.get(message.index) ?? 0), 0) / recentReplies.length;
    if (requestTokens + avgReply > budget.usable) {
      body.append(el('p', { class: 'tam-hint tam-hint-warn' },
        '按最近回复长度，下一轮预计会超出预算：现在压缩一次，或把保留轮数调小。'));
    }
  }

  const needMessages = Number(settings.keepTurns) * 2 + 3;
  if (visible.length < needMessages) {
    body.append(el('p', { class: 'tam-hint' },
      `再聊 ${needMessages - visible.length} 条消息就能开始压缩（保留 ${settings.keepTurns} 轮需要至少 ${needMessages} 条）。`));
  }

  if (measured && measured.prompt >= budget.usable) {
    body.append(el('p', { class: 'tam-hint tam-hint-warn' },
      `上次真实请求 ${measured.prompt.toLocaleString()} tokens 已超过可用预算 ${budget.usable.toLocaleString()}：其中静态前缀 ${measured.prefix.toLocaleString()} 无法压缩。请换小预设、提高有效预算，或直接换模型。`));
  } else if (!measured && visible.length < needMessages && total.tokens >= budget.usable) {
    body.append(el('p', { class: 'tam-hint tam-hint-warn' },
      `仅聊天记录就已 ${total.tokens.toLocaleString()} tokens，超过可用预算 ${budget.usable.toLocaleString()}；预设 / 角色卡的静态前缀还没算进去，压缩历史没有意义，请换小预设或提高有效预算。`));
  }

  if (measured?.truncated) {
    body.append(el('p', { class: 'tam-hint tam-hint-warn' },
      `上次回复用到 ${measured.completion.toLocaleString()}/${measured.maxOut.toLocaleString()} tokens，可能被截断：把模型「最大输出」调大，或关掉预设里的长思维链。`));
  }

  if (budget.override === 0 && budget.rawLimit > budget.usable * 4) {
    body.append(el('p', { class: 'tam-hint tam-hint-warn' },
      `酒馆上下文设为 ${budget.rawLimit.toLocaleString()}，自动压缩几乎不会触发。建议把“有效预算”设成模型真实上限。`));
  }

  body.append(el('div', { class: 'tam-ctxsettings-toggle' },
    el('button', {
      type: 'button',
      'aria-expanded': ctxSettingsOpen ? 'true' : 'false',
      onclick: () => {
        ctxSettingsOpen = !ctxSettingsOpen;
        void renderContext();
      },
    }, ctxSettingsOpen ? '▾ 收起压缩设置' : '⚙ 压缩设置（自动 / 保留轮数 / 预算）'),
  ));

  const recPromise = ctxSettingsOpen
    ? ctxRecommendBudget(visible, requestTokens).catch(() => null)
    : Promise.resolve(null);

  if (ctxSettingsOpen) body.append(
    el('div', { class: 'tam-ctxcontrols' },
      el('label', { class: 'tam-toggle tam-ctx-auto', for: 'tam-ctx-auto' },
        (() => {
          const input = el('input', { id: 'tam-ctx-auto', type: 'checkbox' });
          input.checked = !!settings.auto;
          input.addEventListener('change', () => {
            saveCtxSettings({ auto: input.checked });
            toast(input.checked ? '已开启自动压缩' : '已关闭自动压缩');
          });
          return input;
        })(),
        el('span', { class: 'tam-toggle-track', 'aria-hidden': 'true' }),
        el('span', { class: 'tam-toggle-text' }, '自动压缩'),
      ),
      el('label', { class: 'tam-ctxfield' },
        (() => {
          const input = el('input', { type: 'checkbox' });
          input.checked = settings.confirmSend !== false;
          input.addEventListener('change', () => {
            saveCtxSettings({ confirmSend: input.checked });
            toast(input.checked ? '发送总结前会确认' : '发送总结不再确认');
          });
          return input;
        })(),
        el('span', {}, '发送前确认'),
      ),
      el('div', { class: 'tam-ctxfield' },
        el('span', {}, '每聊'),
        ctxSelect('tam-ctx-every', [[0, '不按轮数'], [2, '2 轮'], [3, '3 轮'], [4, '4 轮'], [5, '5 轮'], [10, '10 轮'], [15, '15 轮'], [20, '20 轮']], settings.autoEvery, (event) => {
          saveCtxSettings({ autoEvery: Number(event.target.value) || 0 });
        }),
        el('span', {}, '自动压一次'),
      ),
      el('p', { class: 'tam-hint' },
        `总结会发送到当前激活连接：${ctxActiveConnection()?.name ?? '未选择'}；自动压缩同样会发送。`),
      el('div', { class: 'tam-ctxseg' },
        ...[['summary', '压缩总结'], ['hide', '只隐藏']].map(([value, label]) =>
          el('button', {
            class: `tam-seg${settings.strategy === value ? ' is-on' : ''}`,
            type: 'button',
            onclick: () => {
              saveCtxSettings({ strategy: value });
              void renderContext();
            },
          }, label)),
      ),
      el('div', { class: 'tam-ctxseg' },
        ...[['rows', '条目式（省 token）'], ['prose', '段落式']].map(([value, label]) =>
          el('button', {
            class: `tam-seg${(settings.summaryStyle === 'prose' ? 'prose' : 'rows') === value ? ' is-on' : ''}`,
            type: 'button',
            onclick: () => {
              saveCtxSettings({ summaryStyle: value });
              toast(value === 'rows' ? '之后的总结按条目输出' : '之后的总结按段落输出');
              void renderContext();
            },
          }, label)),
      ),
      el('div', { class: 'tam-ctxseg' },
        ...[['keep', '图片：保留整楼'], ['trim', '压图模式']].map(([value, label]) =>
          el('button', {
            class: `tam-seg${(settings.imagePolicy === 'trim' ? 'trim' : 'keep') === value ? ' is-on' : ''}`,
            type: 'button',
            onclick: () => {
              saveCtxSettings({ imagePolicy: value });
              toast(value === 'trim'
                ? '之后的图片楼层保留标签、压掉正文；撤销可恢复原文'
                : '图片楼层不再压缩，图片不会被吞');
              void renderContext();
            },
          }, label)),
      ),
      el('div', { class: 'tam-ctxfield' },
        el('span', {}, '保留最近'),
        ctxSelect('tam-ctx-keep', [[4, '4 轮'], [6, '6 轮'], [8, '8 轮'], [12, '12 轮']], settings.keepTurns, (event) => {
          saveCtxSettings({ keepTurns: Number(event.target.value) || 6 });
          void renderContext();
        }),
      ),
      el('div', { class: 'tam-ctxfield' },
        el('span', {}, '有效预算'),
        ctxSelect('tam-ctx-budget', ctxBudgetOptions(settings.budgetOverride), settings.budgetOverride, (event) => {
          saveCtxSettings({ budgetOverride: Number(event.target.value) || 0 });
          void renderContext();
        }),
      ),
      el('div', { id: 'tam-ctx-rec-slot', class: 'tam-hint', style: 'flex:1 0 100%;margin:0' }, '正在计算建议档位…'),
      el('p', { class: 'tam-hint' },
        '参考：500 字 → 3 万；1000 字 → 5 万；2000 字 → 5–9 万；5000 字 → 11 万；1 万字 → 13–17 万；2 万字 → 30 万+（需模型支持）。'),
    ),
  );

  body.append(
    el('div', { class: 'tam-ctxactions' },
      el('button', {
        class: 'tam-primary',
        type: 'button',
        ...(ctxBusy || ctxGenerating ? { disabled: 'disabled' } : {}),
        onclick: () => { void ctxCompress({ auto: false }); },
      }, settings.strategy === 'hide' ? '隐藏旧消息' : '立即压缩'),
      el('button', {
        class: 'tam-ghost',
        type: 'button',
        ...(!meta ? { disabled: 'disabled' } : {}),
        onclick: () => { void ctxUndo(); },
      }, '撤销'),
      el('button', {
        class: 'tam-ghost',
        type: 'button',
        onclick: () => { void ctxUnhideAll(); },
      }, '全部取消隐藏'),
    ),
  );

  body.append(
    el('div', { class: 'tam-ctxrange' },
      el('span', { class: 'tam-ctxrange-label' }, '楼层'),
      el('input', {
        id: 'tam-ctx-from',
        class: 'tam-ctxnum-input',
        type: 'number',
        min: '0',
        inputmode: 'numeric',
        placeholder: '从',
        'aria-label': '起始楼层',
      }),
      el('span', { class: 'tam-ctxrange-to' }, '到'),
      el('input', {
        id: 'tam-ctx-to',
        class: 'tam-ctxnum-input',
        type: 'number',
        min: '0',
        inputmode: 'numeric',
        placeholder: '结束',
        'aria-label': '结束楼层',
      }),
      el('div', { class: 'tam-ctxrange-actions' },
        el('button', {
          class: 'tam-ghost',
          type: 'button',
          onclick: async () => { if (await ctxRangeSelect()) void ctxHideSelected(true); },
        }, '隐藏'),
        el('button', {
          class: 'tam-ghost',
          type: 'button',
          onclick: async () => { if (await ctxRangeSelect()) void ctxHideSelected(false); },
        }, '取消隐藏'),
        el('button', {
          class: 'tam-ghost is-danger',
          type: 'button',
          onclick: async () => { if (await ctxRangeSelect()) void ctxDeleteSelected(); },
        }, '删除'),
      ),
    ),
  );

  if (deleted.length) {
    body.append(el('p', { class: 'tam-hint' },
      el('button', {
        class: 'tam-ctxlink',
        type: 'button',
        onclick: () => { void ctxRestoreDelete(); },
      }, `恢复最近删除（${deleted[0].messages?.length ?? 0} 条）`)));
  }

  if (meta?.summary) {
    const summaryText = String(meta.summary);
    const length = summaryText.length;
    const rows = ctxParseSummaryRows(summaryText);
    const peek = rows.length
      ? rows.slice(0, 3).map((row) => `${row.no}. ${row.place}｜${row.event}｜${row.result}`).join('\n')
      : (length > 120 ? `${summaryText.slice(0, 120)}…` : summaryText);
    body.append(
      el('div', { class: 'tam-ctxsummary' },
        el('div', { class: 'tam-ctxsummary-head' },
          rows.length ? `已压缩 #${meta.start}–#${meta.end} · ${rows.length} 条 · ${length} 字` : `已压缩 #${meta.start}–#${meta.end} · ${length} 字`),
