  gap: 7px;
}

#tam-root .tam-ctxrange-actions button {
  flex: 1 1 0;
  height: 30px;
  padding: 0 6px;
  font-size: 11px;
}

#tam-root .tam-ctxsummary {
  border: 1px solid var(--tam-border);
  background: rgba(94, 106, 210, 0.1);
  padding: 9px 11px;
  margin-bottom: 12px;
}

#tam-root .tam-ctxsummary-head {
  font-size: 10.5px;
  color: var(--tam-accent-2);
  margin-bottom: 4px;
}

#tam-root .tam-ctxsummary p {
