  white-space: pre-line;
}

#tam-root .tam-ctxsummary-actions {
  display: flex;
  gap: 12px;
  margin-top: 6px;
}

#tam-root .tam-ctxlisthead {
  display: flex;
  justify-content: space-between;
  font-size: 10.5px;
  color: var(--tam-fg-dim);
  margin: 0 2px 4px;
}

#tam-root .tam-ctxrow {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 6px;
  border-radius: 10px;
}

#tam-root .tam-ctxrow:nth-child(odd) {
  background: rgba(255, 255, 255, 0.025);
}

#tam-root .tam-ctxrow-hidden {
  opacity: 0.45;
}

#tam-root .tam-ctxidx {
  width: 30px;
  flex: none;
  font-size: 10px;
  color: var(--tam-fg-dim);
}

#tam-root .tam-ctxwho {
  width: 46px;
  flex: none;
  font-size: 10.5px;
  color: #9aa0ad;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

#tam-root .tam-ctxwho.is-user {
  color: #9fb0ff;
}

#tam-root .tam-ctxtext {
  flex: 1;
  min-width: 0;
  font-size: 11.5px;
  color: #cfd2da;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#tam-root .tam-ctxtok {
  flex: none;
  font-size: 10.5px;
  color: var(--tam-fg-dim);
  font-variant-numeric: tabular-nums;
}

#tam-root .tam-ctxrow {
  cursor: pointer;
}

#tam-root .tam-ctxrow.is-sel {
  background: rgba(94, 106, 210, 0.14);
}

#tam-root .tam-ctxcb {
  width: 15px;
