  border-color: rgba(248, 113, 113, 0.3);
}


/* ---------- 压缩预览 ---------- */

#tam-ctx-preview,
#tam-ctx-summary-view {
  position: fixed;
  inset: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(3, 4, 8, 0.62);
  backdrop-filter: blur(2px);
  pointer-events: auto;
}

#tam-ctx-preview-card,
#tam-ctx-summary-card {
  width: min(420px, 100%);
  max-height: min(76vh, 560px);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--tam-border);
  border-radius: 20px;
  background: linear-gradient(180deg, #141727, #0b0d15);
  box-shadow: var(--tam-shadow);
}

#tam-ctx-preview-card h3,
#tam-ctx-summary-card h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

#tam-ctx-preview-text,
#tam-ctx-summary-text {
  width: 100%;
  min-height: 140px;
  flex: 1;
  resize: vertical;
  padding: 9px 10px;
  border: 1px solid var(--tam-border);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--tam-fg);
  font: inherit;
  font-size: 12px;
  line-height: 1.6;
}

#tam-ctx-preview-text:focus,
#tam-ctx-summary-text:focus {
  outline: none;
  border-color: rgba(139, 147, 255, 0.65);
  box-shadow: 0 0 0 3px rgba(94, 106, 210, 0.22);
}

#tam-ctx-preview-est,
#tam-ctx-summary-est {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid rgba(52, 211, 153, 0.22);
  border-radius: 10px;
  background: rgba(52, 211, 153, 0.09);
  color: #9ee9c9;
  font-size: 11.5px;
}

#tam-ctx-preview-card .tam-ctxactions,
#tam-ctx-summary-card .tam-ctxactions {
  margin: 0;
}

#tam-root .tam-ctxsettings-toggle button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border: 1px solid var(--tam-border);
  border-radius: 999px;
  background: var(--tam-surface);
  color: var(--tam-accent-2);
  font: inherit;
  font-size: 11px;
}

#tam-root .tam-ctxsettings-toggle button:hover {
  background: var(--tam-surface-strong);
}

/* ---------------------------------------------------------------- *
 * 防御性圆角：部分酒馆主题/扩展会用
 *   * { border-radius: 0 !important }
 * 把页面所有圆角抹平（伪元素不受影响，所以会出现“方按钮 + 圆旋钮”）。
 * 这里用 #tam-root 的更高优先级 + !important 保住本扩展自己的外形。
 * ---------------------------------------------------------------- */
#tam-root * {
  border-radius: 14px !important;
}

#tam-panel,
#tam-root .tam-modal-card {
  border-radius: 24px !important;
}

/* 大卡片/总结卡片保留更圆的角，不被上面的 14px 防御规则压平 */
#tam-root .tam-ctxcard,
#tam-root #tam-ctx-preview-card,
#tam-root #tam-ctx-summary-card {
  border-radius: 20px !important;
}

#tam-fab,
#tam-root .tam-avatar,
#tam-root .tam-empty-icon,
#tam-root .tam-toggle-track::after {
  border-radius: 50% !important;
}

#tam-root .tam-toggle-track,
#tam-root .tam-chip,
#tam-root .tam-badge,
#tam-root .tam-ctxbar,
#tam-root .tam-ctxpct,
#tam-toast {
  border-radius: 999px !important;
}

#tam-root .tam-ctxcb {
  border-radius: 5px !important;
}







/* 诊断：最近错误 / 开发者模式 */
#tam-root .tam-errors {
  margin-top: 10px;
  border: 1px solid var(--tam-border);
  border-radius: var(--tam-radius);
  background: rgba(255, 255, 255, 0.03);
  padding: 8px 10px;
}
#tam-root .tam-errors-title {
  font-size: 12px;
  color: var(--tam-fg-dim);
  margin-bottom: 6px;
}
#tam-root .tam-errors-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 160px;
  overflow: auto;
}
#tam-root .tam-error {
  font-size: 11px;
  line-height: 1.5;
  color: var(--tam-fg-dim);
  word-break: break-word;
}
#tam-root .tam-error.is-warn { color: #f0c674; }
#tam-root .tam-error.is-info { color: #8fb8ff; }
#tam-root .tam-dev-mode-content {
  margin-top: 10px;
  padding: 10px;
  border: 1px dashed var(--tam-border);
  border-radius: var(--tam-radius);
}
#tam-root .tam-btn {
  pointer-events: auto;
  border: 1px solid var(--tam-border);
  background: var(--tam-surface);
  color: var(--tam-fg);
  border-radius: var(--tam-radius-sm);
  padding: 7px 10px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
#tam-root .tam-btn.is-danger { color: #ff8a8a; border-color: rgba(255, 138, 138, 0.35); }

/* 压缩总结：条目表格 */
#tam-root .tam-summary-table {
  margin: 8px 0;
  border: 1px solid var(--tam-border);
  border-radius: var(--tam-radius);
  overflow: hidden;
  font-size: 12px;
  flex: 0 0 auto;
}
#tam-root .tam-summary-row {
  display: grid;
  grid-template-columns: 26px 64px minmax(0, 1.6fr) minmax(0, 1fr);
  gap: 6px;
  padding: 6px 8px;
  border-top: 1px solid var(--tam-border);
  line-height: 1.45;
}
#tam-root .tam-summary-row:first-child { border-top: 0; }
#tam-root .tam-summary-row.is-head {
  background: rgba(255, 255, 255, 0.04);
  color: var(--tam-fg-dim);
  font-size: 11px;
}
#tam-root .tam-summary-row > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
#tam-root .tam-summary-row .is-no { color: var(--tam-accent); text-align: center; }
#tam-root .tam-summary-editor { margin-top: 8px; flex: 0 0 auto; }
#tam-root .tam-summary-editor-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: var(--tam-fg-dim);
  margin-bottom: 4px;
}


@media (max-width: 620px) {
  #tam-root .tam-summary-row {
    grid-template-columns: 20px 48px minmax(0, 1.5fr) minmax(0, 1fr);
    gap: 4px;
    padding: 5px 6px;
    font-size: 11px;
  }
}


/* 手机端「上下文」不能无限高：键盘弹出时仍要留出可视区 */
@media (max-width: 620px), (pointer: coarse) {
  #tam-panel.tam-ctx-tall {
    height: auto;
    max-height: calc(64dvh - var(--tam-keyboard, 0px));
  }
}
